.hero-heading {
    /* clamp(min, preferred, max)
       48px at mobile, scales with 8vw, caps at 88px 
    */
    font-size: clamp(48px, 8vw, 88px);

    /* Fluid letter-spacing scaled proportionally */
    letter-spacing: clamp(-1.2px, -0.2vw, -2.2px);

    font-family: 'Canela', 'Instrument Serif', serif;
    color: rgb(245, 241, 232);
    line-height: 1;
    margin-bottom: clamp(32px, 4vw, 40px);
    text-wrap: balance; /* Prevents awkward single words on a new line */
  }

  .text-muted {
    color: rgba(245, 241, 232, 0.72);
  }

/* Primary Button Style */
.primary-btn {
    display: inline-flex !important;
    align-items: center !important;
    gap: 8px !important;
    padding: 0 0 1px 0 !important;
    background: transparent !important;
    border: none !important;
    border-bottom: 1px solid rgba(245, 241, 232, 0.3) !important;
    border-radius: 0 !important;
    cursor: pointer;
    transition: border-color 0.3s ease !important;
    text-decoration: none;
}

/* Hover State */
.primary-btn:hover {
    border-bottom-color: var(--text) !important;
}

/* Structural Overrides for Elementor Buttons */
.primary-btn .elementor-button-content-wrapper {
    display: contents !important;
}

.primary-btn .elementor-button-icon {
    display: none !important;
}

